const menu=document.querySelector('.menu');const links=document.querySelector('.links');if(menu&&links){menu.addEventListener('click',()=>{const open=links.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});links.addEventListener('click',()=>links.classList.remove('open'))}document.querySelectorAll('[data-year]').forEach(el=>el.textContent=new Date().getFullYear());
